<script setup>
import {isAdmin} from '../services/admin'
import {ref,watch} from 'vue';import {api,money,date,safeUrl} from '../services/api'
const props=defineProps({figure:Object,variant:[Number,String]});const value=ref(null),error=ref(''),busy=ref(false),preview=ref(null)
const form=ref({source_url:'',amount:'',price_kind:'korea_official_sale',confirmed_same_product:false})
let generation=0
async function load(){const n=++generation;value.value=null;error.value='';if(!props.variant)return;try{const data=await api(`/figures/${props.figure.id}/local-prices?variant_id=${props.variant}`);if(n===generation)value.value=data}catch(e){if(n===generation)error.value=e.message}}
watch(()=>[props.figure.id,props.variant],()=>{preview.value=null;form.value.confirmed_same_product=false;load()},{immediate:true})
async function lookup(){busy.value=true;error.value='';try{preview.value=await api('/korea-prices/preview',{method:'POST',body:{source_url:form.value.source_url}});form.value.amount=preview.value.amount}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{await api('/korea-prices',{method:'POST',body:{...form.value,variant_id:Number(props.variant)}});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(){if(!confirm('이 한국 공식 가격 기록을 삭제할까요?'))return;try{await api('/korea-prices/'+value.value.korea.id,{method:'DELETE'});await load()}catch(e){error.value=e.message}}
async function refresh(){busy.value=true;try{await api('/exchange-rate/refresh',{method:'POST'});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="personal-panel"><h2>공식 가격 · 원화 환산</h2><p class="error" v-if="error">{{error}}</p><template v-if="value"><p><strong>한국 공식 {{value.korea?.price_kind==='korea_official_list'?'정가':'판매가'}}</strong> {{value.korea?money(value.korea.price_amount,'KRW'):'미등록'}}</p><p v-if="value.korea"><a :href="safeUrl(value.korea.source_url)" target="_blank" rel="noopener noreferrer">반다이남코코리아몰 출처 ↗</a> · {{date(value.korea.checked_at)}} · 사용자 확인 등록 <button v-if="isAdmin" @click="remove">가격 기록 삭제</button></p><p>일본 공식 표시가: {{value.japan?money(value.japan.price_amount,'JPY'):'미확인'}}</p><p><strong>원화 환산 예상가: {{money(value.estimate_krw,'KRW')}}</strong></p><p v-if="value.rate" class="muted">1 JPY = {{Number(value.rate.rate).toFixed(4)}} KRW · {{value.rate.rate_date}} 기준 · <a :href="safeUrl(value.rate.source_url)" target="_blank" rel="noopener noreferrer">Frankfurter</a></p><p v-if="value.error" class="error">{{value.error}}</p><small>환산액은 일본 표시가 기준 참고 금액입니다. 배송비·관부가세·카드 수수료는 포함하지 않습니다.</small><p v-if="isAdmin"><button class="button ghost" :disabled="busy" @click="refresh">환율 갱신</button></p></template>
<details v-if="isAdmin&&figure.manufacturer==='Bandai Spirits'"><summary>한국 공식 가격 등록 / 수정</summary><form @submit.prevent="save"><label>반다이남코코리아몰 상품 URL<input v-model="form.source_url" type="url" required placeholder="https://www.bnkrmall.co.kr/goods/detail.do?gno=..."></label><button class="button ghost" type="button" :disabled="busy" @click="lookup">공식 페이지에서 가격 가져오기</button><p v-if="preview">조회 상품: {{preview.name}} · JAN: {{preview.jan_code||'미확인'}}</p><label>확인한 원화 금액<input type="number" v-model="form.amount" min="1" max="999999999" step="1" required></label><label>가격 종류<select v-model="form.price_kind"><option value="korea_official_sale">공식 판매가</option><option value="korea_official_list">공식 정가 (원문에서 정가 확인 시)</option></select></label><label class="check-label"><input type="checkbox" v-model="form.confirmed_same_product" required> 공식 페이지의 상품명·제품번호·버전이 현재 상품과 같은지 확인했습니다.</label><button class="button" :disabled="busy">가격 저장</button></form></details></section></template>
